Running command: python3 - <<'PY'
# Generate raw deflate fixed block: final=1 btype=1, sym 257 len3, dist sym0 dist1, end 256
# Canonical fixed codes per RFC: 256-279: 7 bits values 0..23, bit-reversed transmitted

def revbits(v,n):
    r=0
    for i in range(n): r=(r<<1)|((v>>i)&1)
    return r
# actually writer emits LSB-first numeric code; if canonical MSB code C length n, write bits reversed? When adding bits LSB-first use C reversed as low bits.
class BW:
    def __init__(self): self.bits=[]
    def put(self,v,n):
        for i in range(n): self.bits.append((v>>i)&1)
    def bytes(self):
        out=[]
        for i in range(0,len(self.bits),8):
            b=0
            for j in range(8):
                if i+j < len(self.bits): b|=self.bits[i+j]<<j
            out.append(b)
        return bytes(out)

for reverse in [True,False]:
  bw=BW(); bw.put(1,1); bw.put(1,2) # BTYPE fixed = bits 1,0? Oops put value 1 for 2 bits emits 1,0.
  # For BFINAL=1,BTYPE=01 bits: 1,1,0? BTYPE bits LSB first value 1 => bit1 then bit0 yes total 1,1,0
  for sym in [257]:
    c=sym-256; n=7; val=revbits(c,n) if reverse else c; bw.put(val,n)
  bw.put(0,5) # dist 0 fixed distance 5 bits
  sym=256; c=sym-256; val=revbits(c,7) if reverse else c; bw.put(val,7)
  raw=bw.bytes()
  print(reverse, raw.hex(), bw.bits)
  import zlib
  try: print(zlib.decompress(raw, -15))
  except Exception as e: print('err', e)
PY

